import {expansionExperiments} from './expansion-catalog.js?v=54';
// Each entry defines its own physical relationship, controls, observables and limits.
const G=9.81,PI=Math.PI,R=8.314462618,k=8.9875517923e9,mu=4e-7*PI,eps=8.8541878128e-12,e=1.602176634e-19;
const rad=a=>a*PI/180;
const P=(key,label,min,max,value,unit='',step=(max-min)/100,digits=2)=>({key,label,min,max,value,unit,step,digits});
const A=(a,b)=>P(a,b,0,90,30,'°',1,0),M=()=>P('mass','Khối lượng',.2,5,1,'kg',.1),F=()=>P('force','Lực tác dụng',0,30,10,'N',.5),L=()=>P('length','Chiều dài',.2,3,1,'m',.05),U=()=>P('voltage','Điện áp',0,24,12,'V',.5),RR=()=>P('resistance','Điện trở',2,100,20,'Ω',1,0),T=()=>P('temp','Nhiệt độ tuyệt đối',200,600,300,'K',5,0);
const Q=(key,label,unit='',digits=2)=>({key,label,unit,digits,scale:1});
const specs=[];
function add(id,title,topic,scene,params,readouts,formula,compute,insight,{grade=10,extra=false,time=false,limit=''}={}){
 if(time)params.push(P('t','Thời điểm',0,10,0,'s',.01));
 const columns=[...params,...readouts.filter(q=>!params.some(p=>p.key===q.key))].map(p=>({key:p.key,label:p.label+(p.unit?` (${p.unit})`:''),scale:1}));
 const primary=params.find(p=>p.key!=='t'),metric=readouts[0];
 specs.push({id,title,shortTitle:title,topic,grade,extra,scene,compute,params,readouts,columns,headers:columns.map(c=>c.label),formula,description:insight,analysis:insight,theory:formula+'. '+insight,limit:(limit||'Mô hình lí tưởng; các điều kiện khác được giữ theo thiết lập.')+' Kích thước và tốc độ chuyển động trên hình có thể được thay đổi tỉ lệ để quan sát; dùng số đọc để định lượng.',static:!time,playSeconds:time?8:undefined,graph:{key:time?'t':primary.key,metric:metric.key,xLabel:time?'t (s)':columns[0].label,yLabel:metric.label+(metric.unit?` (${metric.unit})`:''),min:time?0:primary.min,max:time?null:primary.max},tasks:[`Thay đổi ${primary.label.toLowerCase()} và dự đoán ${metric.label.toLowerCase()}.`,`Ghi ít nhất 5 trạng thái; mỗi lần chỉ đổi một biến.`,insight],learning:{change:`Thay đổi ${primary.label.toLowerCase()}.`,observe:`Theo dõi ${metric.label.toLowerCase()} và vị trí / biểu diễn có màu.`,explain:insight},narration:`${title}. ${insight} ${formula}`});
}
// 24 mechanics, gravity and fluid investigations.
add('vector_sum','Tổng hợp hai lực','Cơ học','vectors',[F(),P('second','Lực thứ hai',0,30,15,'N',.5),A('angle','Góc giữa hai lực')],[Q('result','Hợp lực','N'),Q('fx','Thành phần x','N'),Q('fy','Thành phần y','N')],'F² = F₁² + F₂² + 2F₁F₂ cosα',s=>({fx:s.force+s.second*Math.cos(rad(s.angle)),fy:s.second*Math.sin(rad(s.angle)),result:Math.hypot(s.force+s.second*Math.cos(rad(s.angle)),s.second*Math.sin(rad(s.angle)))}),'Cùng độ lớn nhưng khác góc, hai lực tạo ra hợp lực khác nhau.');
add('vector_components','Phân tích lực theo hai trục','Cơ học','vectors',[F(),A('angle','Góc với trục x')],[Q('fx','Lực theo x','N'),Q('fy','Lực theo y','N'),Q('result','Độ lớn lực','N')],'Fx = F cosα; Fy = F sinα',s=>({fx:s.force*Math.cos(rad(s.angle)),fy:s.force*Math.sin(rad(s.angle)),result:s.force}),'Góc tăng làm Fx giảm và Fy tăng; độ lớn lực ban đầu giữ nguyên.');
add('relative_motion','Chuyển động trong hai hệ quy chiếu','Cơ học','carts',[P('speed','Vận tốc vật',-8,8,4,'m/s',.2),P('frame','Vận tốc hệ quy chiếu',-5,5,2,'m/s',.2)],[Q('relative','Vận tốc tương đối','m/s'),Q('x','Vị trí vật','m'),Q('frameX','Vị trí hệ','m')],'v tương đối = v vật − v hệ',s=>({relative:s.speed-s.frame,x:s.speed*s.t,frameX:s.frame*s.t}),'Một vật có thể chuyển động sang phải trong hệ này nhưng sang trái trong hệ khác.',{time:true});
add('average_speed','Tốc độ trung bình trên hai chặng','Cơ học','carts',[P('v1','Tốc độ chặng đầu',1,20,5,'m/s',.5),P('v2','Tốc độ chặng sau',1,20,10,'m/s',.5),P('distance','Độ dài mỗi chặng',5,100,30,'m',1)],[Q('average','Tốc độ trung bình','m/s'),Q('t1','Thời gian chặng đầu','s'),Q('t2','Thời gian chặng sau','s')],'v̄ = 2s/(s/v₁ + s/v₂)',s=>({average:2/(1/s.v1+1/s.v2),t1:s.distance/s.v1,t2:s.distance/s.v2}),'Hai chặng bằng nhau về quãng đường không có nghĩa là lấy trung bình cộng hai tốc độ.');
add('braking','Phanh xe và quãng đường dừng','Cơ học','carts',[P('speed','Tốc độ đầu',1,30,15,'m/s',.5),P('deceleration','Độ lớn gia tốc hãm',1,10,5,'m/s²',.2)],[Q('stopDistance','Quãng đường dừng','m'),Q('stopTime','Thời gian dừng','s'),Q('v','Tốc độ hiện tại','m/s')],'s dừng = v₀²/(2a); t dừng = v₀/a',s=>({stopDistance:s.speed**2/(2*s.deceleration),stopTime:s.speed/s.deceleration,v:Math.max(0,s.speed-s.deceleration*s.t),x:(s.speed**2-Math.max(0,s.speed-s.deceleration*s.t)**2)/(2*s.deceleration)}),'Tốc độ đầu tăng gấp đôi làm quãng đường phanh tăng gấp bốn khi gia tốc hãm không đổi.',{time:true});
add('drag_fall','Rơi có lực cản tuyến tính','Cơ học','fall',[M(),P('drag','Hệ số cản',.1,3,.6,'kg/s',.05)],[Q('v','Tốc độ rơi','m/s'),Q('terminal','Tốc độ giới hạn','m/s'),Q('net','Hợp lực','N')],'v = mg/b · (1 − exp(−bt/m))',s=>{const v=s.mass*G/s.drag*(1-Math.exp(-s.drag*s.t/s.mass));return {v,terminal:s.mass*G/s.drag,net:s.mass*G-s.drag*v,x:s.mass*G/s.drag*(s.t-s.mass/s.drag*(1-Math.exp(-s.drag*s.t/s.mass)))};},'Khi lực cản cân bằng trọng lực, vật vẫn rơi với tốc độ không đổi.',{time:true,extra:true,limit:'Lực cản F = bv, vật bắt đầu từ nghỉ. Không mô phỏng mặt đất.'});
add('atwood','Máy Atwood','Cơ học','pulley',[P('m1','Khối lượng bên trái',.2,3,1,'kg',.1),P('m2','Khối lượng bên phải',.2,3,1.5,'kg',.1)],[Q('acc','Gia tốc có dấu','m/s²'),Q('tension','Lực căng','N'),Q('difference','Chênh trọng lượng','N')],'a = (m₂ − m₁)g/(m₁ + m₂)',s=>({acc:(s.m2-s.m1)*G/(s.m1+s.m2),tension:2*s.m1*s.m2*G/(s.m1+s.m2),difference:(s.m2-s.m1)*G}),'Gia tốc phụ thuộc chênh khối lượng lẫn tổng khối lượng.',{limit:'Ròng rọc và dây không khối lượng, không ma sát; hình chỉ thể hiện xu hướng dịch chuyển.'});
add('pulley','Ròng rọc động và lợi về lực','Cơ học','pulley',[M(),P('branches','Số nhánh đỡ',1,4,2,'',1,0),P('lift','Độ nâng tải',.1,2,.5,'m',.1)],[Q('pull','Lực kéo','N'),Q('rope','Dây cần kéo','m'),Q('work','Công kéo','J')],'F = mg/n; s dây = nh',s=>({pull:s.mass*G/s.branches,rope:s.branches*s.lift,work:s.mass*G*s.lift}),'Lợi về lực phải đổi bằng quãng đường kéo dây; công lí tưởng không giảm.',{limit:'Dây, ròng rọc lí tưởng. Số nhánh là số nguyên; sơ đồ biểu diễn nguyên tắc lợi lực.'});
add('elevator','Cân trong thang máy','Cơ học','fall',[M(),P('acc','Gia tốc hướng lên',-G,8,2,'m/s²',.1)],[Q('normal','Số chỉ lực kế','N'),Q('weight','Trọng lực','N'),Q('ratio','Số chỉ / trọng lực')],'N = m(g + a)',s=>({normal:s.mass*(G+s.acc),weight:s.mass*G,ratio:1+s.acc/G}),'Số chỉ cân thay đổi theo gia tốc; khối lượng và trọng lực của vật vẫn giữ nguyên.');
add('banked_turn','Đường vòng nghiêng lí tưởng','Cơ học','orbit',[P('radius','Bán kính đường vòng',5,100,30,'m',1),A('angle','Góc nghiêng')],[Q('speed','Tốc độ phù hợp','m/s'),Q('acc','Gia tốc hướng tâm','m/s²'),Q('ratio','N / mg')],'v = √(rg tanα)',s=>({speed:Math.sqrt(s.radius*G*Math.tan(rad(s.angle))),acc:G*Math.tan(rad(s.angle)),ratio:1/Math.cos(rad(s.angle))}),'Mặt đường nghiêng tạo thành phần lực hướng tâm khi không cần ma sát.',{extra:true,limit:'Bỏ qua ma sát; góc nghiêng không vượt 70°.'});specs.at(-1).params[1].max=70;
add('vertical_circle','Vật ở đỉnh vòng tròn thẳng đứng','Cơ học','orbit',[M(),P('radius','Bán kính',.3,3,1,'m',.1),P('speed','Tốc độ ở đỉnh',0,12,5,'m/s',.2)],[Q('tension','Lực căng cần thiết','N'),Q('minimum','Tốc độ tối thiểu','m/s'),Q('taut','Dây còn căng','',0)],'T = mv²/r − mg; vmin = √(gr)',s=>({tension:Math.max(0,s.mass*(s.speed**2/s.radius-G)),minimum:Math.sqrt(G*s.radius),taut:s.speed**2>=G*s.radius?1:0}),'Tốc độ quá nhỏ làm dây chùng; công thức quỹ đạo tròn không còn áp dụng.',{extra:true});
add('gravitational_force','Hấp dẫn giữa hai quả cầu','Cơ học','gravity',[P('m1','Khối lượng cầu 1',1,100,20,'kg',1),P('m2','Khối lượng cầu 2',1,100,30,'kg',1),P('distance','Khoảng cách tâm',.2,3,1,'m',.05)],[Q('force','Lực hấp dẫn','µN',5),Q('acc','Gia tốc của cầu 2','nm/s²'),Q('ratio','F·r²','µN·m²',5)],'F = GMm/r²',s=>({force:6.6743e-5*s.m1*s.m2/s.distance**2,acc:.066743*s.m1/s.distance**2,ratio:6.6743e-5*s.m1*s.m2}),'Tăng khoảng cách tâm gấp đôi làm lực hấp dẫn giảm bốn lần.',{extra:true});
add('orbit','Vệ tinh trên quỹ đạo tròn','Cơ học','orbit',[P('radius','Bán kính quỹ đạo',6500,30000,7000,'km',100),P('planet','Khối lượng hành tinh',1,10,5.972,'10²⁴ kg',.1)],[Q('speed','Tốc độ quỹ đạo','km/s'),Q('period','Chu kì','phút'),Q('acc','Gia tốc hướng tâm','m/s²')],'v = √(GM/r); T = 2π√(r³/GM)',s=>{const v=Math.sqrt(6.6743e-11*s.planet*1e24/(s.radius*1000));return {speed:v/1000,period:2*PI*s.radius*1000/v/60,acc:v*v/(s.radius*1000)};},'Vệ tinh ở quỹ đạo tròn cao hơn chuyển động chậm hơn và có chu kì dài hơn.',{extra:true});
add('escape_speed','Tốc độ thoát khỏi hành tinh','Cơ học','orbit',[P('radius','Bán kính hành tinh',2000,10000,6371,'km',100),P('planet','Khối lượng hành tinh',1,10,5.972,'10²⁴ kg',.1)],[Q('escape','Tốc độ thoát','km/s'),Q('circular','Tốc độ tròn tại bề mặt','km/s'),Q('ratio','Tỉ số hai tốc độ')],'v thoát = √(2GM/R)',s=>({escape:Math.sqrt(2*6.6743e4*s.planet/s.radius),circular:Math.sqrt(6.6743e4*s.planet/s.radius),ratio:Math.SQRT2}),'Ở cùng bán kính, tốc độ thoát bằng √2 lần tốc độ quỹ đạo tròn.',{extra:true,limit:'Bỏ qua khí quyển, chuyển động quay và ảnh hưởng của các thiên thể khác.'});
add('kepler','Quy luật Kepler III','Cơ học','orbit',[P('axis','Bán trục lớn',.3,5,1,'AU',.1)],[Q('period','Chu kì','năm'),Q('square','T²','năm²'),Q('cube','a³','AU³')],'T²/a³ = hằng số',s=>({period:s.axis**1.5,square:s.axis**3,cube:s.axis**3}),'Quanh cùng một sao, bình phương chu kì tỉ lệ với lập phương bán trục lớn.',{extra:true,limit:'Sao có khối lượng Mặt Trời; khối lượng hành tinh không đáng kể. Hình vẽ dùng quỹ đạo tròn.'});
add('torque_angle','Mômen lực theo góc đặt lực','Cơ học','lever',[F(),L(),A('angle','Góc lực với thanh')],[Q('torque','Mômen lực','N·m'),Q('arm','Cánh tay đòn','m'),Q('perpendicular','Lực vuông góc','N')],'M = Fl sinα',s=>({torque:s.force*s.length*Math.sin(rad(s.angle)),arm:s.length*Math.sin(rad(s.angle)),perpendicular:s.force*Math.sin(rad(s.angle))}),'Lực vuông góc với thanh tạo mômen lớn nhất khi điểm đặt không đổi.');
