add('angular_accel','Gia tốc góc dưới mômen không đổi','Cơ học','rotor',[P('torque','Mômen lực',0,10,2,'N·m',.1),P('inertia','Mômen quán tính',.1,3,1,'kg·m²',.1)],[Q('alpha','Gia tốc góc','rad/s²'),Q('omega','Tốc độ góc','rad/s'),Q('energy','Động năng quay','J')],'α = M/I; ω = αt',s=>({alpha:s.torque/s.inertia,omega:s.torque/s.inertia*s.t,energy:.5*s.inertia*(s.torque/s.inertia*s.t)**2}),'Mômen không đổi làm tốc độ góc tăng đều nếu mômen quán tính không đổi.',{time:true,extra:true});
add('rolling','Lăn không trượt','Cơ học','rotor',[M(),P('speed','Tốc độ tâm',0,10,3,'m/s',.2),P('radius','Bán kính trụ',.1,1,.3,'m',.02)],[Q('omega','Tốc độ góc','rad/s'),Q('translation','Động năng tịnh tiến','J'),Q('rotation','Động năng quay','J')],'v = ωR; K = ½mv² + ¼mv²',s=>({omega:s.speed/s.radius,translation:.5*s.mass*s.speed**2,rotation:.25*s.mass*s.speed**2}),'Trụ đặc lăn có cả động năng tịnh tiến và động năng quay.',{extra:true,limit:'Trụ đặc đồng chất, lăn không trượt. Không tính tổn hao do cản lăn.'});
add('spring_energy','Công biến dạng lò xo','Cơ học','spring',[P('stiffness','Độ cứng',10,200,50,'N/m',5),P('extension','Độ biến dạng',0,.5,.2,'m',.01)],[Q('energy','Thế năng đàn hồi','J'),Q('force','Lực đàn hồi','N'),Q('average','Lực trung bình khi kéo','N')],'W = ½kx²',s=>({energy:.5*s.stiffness*s.extension**2,force:s.stiffness*s.extension,average:.5*s.stiffness*s.extension}),'Độ biến dạng gấp đôi làm thế năng đàn hồi tăng gấp bốn trong giới hạn Hooke.');
add('elastic_modulus','Kéo dãn một sợi dây','Cơ học','spring',[F(),L(),P('area','Tiết diện',.1,2,.5,'mm²',.05),P('young','Môđun Young',10,200,100,'GPa',5)],[Q('extension','Độ dãn','mm',4),Q('stress','Ứng suất','MPa'),Q('strain','Biến dạng tương đối','µstrain')],'Δl = Fl/(ES)',s=>({extension:s.force*s.length/(s.young*s.area),stress:s.force/s.area,strain:s.force/(s.young*s.area)*1000}),'Dây dài hoặc mảnh hơn dãn nhiều hơn dưới cùng lực kéo.',{extra:true,limit:'Đàn hồi tuyến tính, chưa xét giới hạn bền và biến dạng dẻo. Độ dãn hình được phóng đại.'});
add('hydraulic_press','Máy ép thủy lực','Chất lưu','hydraulic',[F(),P('small','Tiết diện pít tông nhỏ',1,10,2,'cm²',.5),P('large','Tiết diện pít tông lớn',10,100,30,'cm²',1)],[Q('output','Lực nâng','N'),Q('pressure','Áp suất dư','kPa'),Q('ratio','Lợi lực')],'F₂/F₁ = S₂/S₁',s=>({output:s.force*s.large/s.small,pressure:s.force/s.small*10,ratio:s.large/s.small}),'Áp suất truyền qua chất lỏng giúp pít tông lớn tạo lực lớn hơn.',{limit:'Chất lỏng không nén được; bỏ qua chênh cao, ma sát và khối lượng pít tông.'});
add('communicating','Bình thông nhau với hai chất lỏng','Chất lưu','fluid',[P('density1','Khối lượng riêng cột 1',700,1300,800,'kg/m³',10),P('density2','Khối lượng riêng cột 2',700,1300,1000,'kg/m³',10),P('height','Chiều cao cột 1',.1,1,.5,'m',.02)],[Q('height2','Chiều cao cột 2','m'),Q('pressure','Áp suất dư tại đáy','kPa'),Q('ratio','h₂ / h₁')],'ρ₁gh₁ = ρ₂gh₂',s=>({height2:s.density1*s.height/s.density2,pressure:s.density1*G*s.height/1000,ratio:s.density1/s.density2}),'Hai cột lỏng có khối lượng riêng khác nhau không có cùng chiều cao cân bằng.',{limit:'Hai chất lỏng không trộn; hai mặt thoáng cùng chịu áp suất khí quyển.'});
add('torricelli','Tia nước từ lỗ nhỏ','Chất lưu','fluid',[P('height','Độ cao mặt nước trên lỗ',.1,3,1,'m',.05),P('area','Tiết diện lỗ',.1,2,.5,'cm²',.1)],[Q('speed','Tốc độ tia nước','m/s'),Q('flow','Lưu lượng','L/s'),Q('pressure','Áp suất dư trước lỗ','kPa')],'v = √(2gh); Q = Sv',s=>({speed:Math.sqrt(2*G*s.height),flow:s.area*.1*Math.sqrt(2*G*s.height),pressure:G*s.height}),'Mặt nước cao hơn tạo tia chảy nhanh hơn; lỗ rộng hơn làm tăng lưu lượng.',{extra:true,limit:'Bình rộng, lỗ nhỏ; dòng ổn định, chất lỏng không nhớt. Mực nước được giữ cố định.'});
// 18 oscillation and wave investigations.
add('spring_period','Chu kì con lắc theo khối lượng','Dao động','spring',[M(),P('stiffness','Độ cứng',10,100,40,'N/m',2)],[Q('period','Chu kì','s'),Q('frequency','Tần số','Hz'),Q('omega','Tần số góc','rad/s')],'T = 2π√(m/k)',s=>({period:2*PI*Math.sqrt(s.mass/s.stiffness),frequency:Math.sqrt(s.stiffness/s.mass)/(2*PI),omega:Math.sqrt(s.stiffness/s.mass)}),'Tăng khối lượng bốn lần làm chu kì tăng hai lần.',{grade:11});
add('oscillator_energy','Năng lượng theo pha dao động','Dao động','spring',[P('amplitude','Biên độ',.01,.2,.1,'m',.005),P('stiffness','Độ cứng',10,100,40,'N/m',2),M()],[Q('kinetic','Động năng','J'),Q('potential','Thế năng','J'),Q('total','Cơ năng','J')],'E = ½kA²; K + U = E',s=>{const phase=Math.sqrt(s.stiffness/s.mass)*s.t,x=s.amplitude*Math.cos(phase);return {x,potential:.5*s.stiffness*x*x,kinetic:.5*s.stiffness*(s.amplitude**2-x*x),total:.5*s.stiffness*s.amplitude**2};},'Thế năng lớn nhất ở biên; động năng lớn nhất tại vị trí cân bằng.',{grade:11,time:true});
add('phase_difference','Hai dao động lệch pha','Dao động','dualwave',[P('phase','Độ lệch pha',0,360,90,'°',5,0),P('amplitude','Biên độ mỗi dao động',.1,1,.5,'cm',.05),P('frequency','Tần số',.2,2,1,'Hz',.1)],[Q('x1','Li độ 1','cm'),Q('x2','Li độ 2','cm'),Q('sum','Tổng li độ','cm')],'x₂ = A cos(ωt + Δφ)',s=>({x1:s.amplitude*Math.cos(2*PI*s.frequency*s.t),x2:s.amplitude*Math.cos(2*PI*s.frequency*s.t+rad(s.phase)),sum:s.amplitude*(Math.cos(2*PI*s.frequency*s.t)+Math.cos(2*PI*s.frequency*s.t+rad(s.phase)))}),'Hai dao động cùng biên độ có thể triệt tiêu khi ngược pha.',{grade:11,time:true});
add('beat','Phách của hai tần số gần nhau','Sóng','dualwave',[P('f1','Tần số thứ nhất',1,5,3,'Hz',.1),P('difference','Độ chênh tần số',.1,1,.3,'Hz',.05)],[Q('beat','Tần số phách','Hz'),Q('envelope','Biên độ bao tương đối'),Q('signal','Li độ tổng tương đối')],'f phách = |f₂ − f₁|',s=>({beat:s.difference,envelope:2*Math.abs(Math.cos(PI*s.difference*s.t)),signal:Math.cos(2*PI*s.f1*s.t)+Math.cos(2*PI*(s.f1+s.difference)*s.t)}),'Hai tần số gần nhau tạo biên độ tổng mạnh lên rồi yếu đi theo nhịp phách.',{grade:11,time:true,extra:true});
add('doppler_source','Doppler khi nguồn tiến lại','Sóng','soundrings',[P('source','Tốc độ nguồn tiến về đầu thu',0,100,30,'m/s',2),P('frequency','Tần số nguồn',100,1000,440,'Hz',10,0)],[Q('received','Tần số nhận','Hz'),Q('front','Bước sóng phía trước','m'),Q('behind','Bước sóng phía sau','m')],'f′ = fv/(v − vs)',s=>({received:s.frequency*343/(343-s.source),front:(343-s.source)/s.frequency,behind:(343+s.source)/s.frequency}),'Nguồn tiến lại làm các mặt sóng phía trước dồn gần nhau.',{grade:11,extra:true,limit:'Không khí đứng yên, v âm = 343 m/s; đầu thu đứng yên, nguồn chuyển động thẳng dưới tốc độ âm.'});
add('doppler_observer','Doppler khi người nghe chuyển động','Sóng','soundrings',[P('observer','Tốc độ đầu thu hướng về nguồn',-100,100,30,'m/s',2),P('frequency','Tần số nguồn',100,1000,440,'Hz',10,0)],[Q('received','Tần số nhận','Hz'),Q('wavelength','Bước sóng trong không khí','m'),Q('ratio','f′ / f')],'f′ = f(v + vo)/v',s=>({received:s.frequency*(343+s.observer)/343,wavelength:343/s.frequency,ratio:(343+s.observer)/343}),'Người nghe chuyển động làm đổi tần số gặp sóng, không làm đổi bước sóng trong không khí.',{grade:11,extra:true});
add('string_speed','Tốc độ sóng trên dây căng','Sóng','wave',[P('tension','Lực căng',1,100,25,'N',1),P('linear','Khối lượng trên mét dây',1,20,5,'g/m',.5)],[Q('speed','Tốc độ truyền','m/s'),Q('wavelength','Bước sóng ở 10 Hz','m'),Q('ratio','v² / F','m/kg')],'v = √(F/µ)',s=>({speed:Math.sqrt(1000*s.tension/s.linear),wavelength:Math.sqrt(1000*s.tension/s.linear)/10,ratio:1000/s.linear}),'Dây căng hơn truyền sóng nhanh hơn; dây nặng hơn truyền chậm hơn.',{grade:11});
add('string_resonance','Các họa âm của dây đàn','Sóng','standing',[L(),P('tension','Lực căng',1,100,25,'N',1),P('mode','Bậc họa âm',1,6,2,'',1,0)],[Q('frequency','Tần số họa âm','Hz'),Q('fundamental','Tần số cơ bản','Hz'),Q('wavelength','Bước sóng','m')],'fn = nv/(2L)',s=>({frequency:s.mode*Math.sqrt(s.tension/.005)/(2*s.length),fundamental:Math.sqrt(s.tension/.005)/(2*s.length),wavelength:2*s.length/s.mode}),'Dây có hai đầu cố định chỉ cộng hưởng ở những tần số phù hợp điều kiện biên.',{grade:11,limit:'Dây đồng nhất µ = 0,005 kg/m, hai đầu là nút; bỏ qua độ cứng uốn và suy hao.'});
add('open_pipe','Cộng hưởng ống sáo hai đầu hở','Sóng','pipe',[L(),P('mode','Bậc họa âm',1,6,2,'',1,0)],[Q('frequency','Tần số cộng hưởng','Hz'),Q('wavelength','Bước sóng','m'),Q('fundamental','Tần số cơ bản','Hz')],'fn = nv/(2L)',s=>({frequency:s.mode*343/(2*s.length),wavelength:2*s.length/s.mode,fundamental:343/(2*s.length)}),'Hai đầu hở là bụng li độ của không khí và là nút biến thiên áp suất.',{grade:11,extra:true,limit:'Biểu diễn đường bao li độ, không phải hình dạng dòng khí. Bỏ qua hiệu chỉnh đầu ống.'});
add('closed_pipe','Ống khí một đầu kín','Sóng','pipe',[L(),P('mode','Thứ tự mode',1,5,2,'',1,0)],[Q('frequency','Tần số cộng hưởng','Hz'),Q('wavelength','Bước sóng','m'),Q('harmonic','Bậc họa âm lẻ','',0)],'fn = (2n − 1)v/(4L)',s=>({frequency:(2*s.mode-1)*343/(4*s.length),wavelength:4*s.length/(2*s.mode-1),harmonic:2*s.mode-1}),'Đầu kín là nút li độ, đầu hở là bụng li độ; chỉ có họa âm lẻ trong mô hình.',{grade:11,extra:true,limit:'Biểu diễn đường bao li độ. Bỏ qua hiệu chỉnh đầu ống; vận tốc âm 343 m/s.'});
add('sound_level','Mức cường độ âm và thang decibel','Sóng','soundrings',[P('exponent','Số mũ của I (W/m²)',-12,-2,-6,'',.1)],[Q('level','Mức cường độ âm','dB'),Q('intensity','Cường độ âm','µW/m²',5),Q('ratio','I / I₀','',0)],'L = 10 log₁₀(I/I₀)',s=>({level:10*(s.exponent+12),intensity:10**(s.exponent+6),ratio:10**(s.exponent+12)}),'Tăng cường độ 10 lần làm mức cường độ tăng 10 dB, không phải tăng 10 lần số dB.',{grade:11,limit:'I₀ = 10⁻¹² W/m². Mức cường độ không đồng nhất với cảm giác độ to chủ quan.'});
add('intensity_distance','Âm từ nguồn điểm theo khoảng cách','Sóng','soundrings',[P('distance','Khoảng cách tới nguồn',1,20,5,'m',.5),P('power','Công suất âm',.001,.1,.01,'W',.001,3)],[Q('intensity','Cường độ','µW/m²'),Q('level','Mức cường độ','dB'),Q('area','Diện tích mặt cầu','m²')],'I = P/(4πr²)',s=>({intensity:s.power/(4*PI*s.distance**2)*1e6,level:10*Math.log10(s.power/(4*PI*s.distance**2)/1e-12),area:4*PI*s.distance**2}),'Ra xa nguồn gấp đôi làm cường độ còn một phần tư nếu không hấp thụ hay phản xạ.',{grade:11});
add('standing_phase','Tổng hai sóng ngược chiều','Sóng','standing',[P('probe','Vị trí khảo sát',0,2,.5,'m',.02),P('phase','Pha tương đối hai nguồn',0,360,0,'°',5,0)],[Q('signal','Li độ tại điểm','cm'),Q('envelope','Biên độ tại điểm','cm'),Q('x','Tọa độ điểm','m')],'u = cos(ωt − kx) + cos(ωt + kx + φ)',s=>({signal:Math.cos(2*PI*s.t-PI*s.probe)+Math.cos(2*PI*s.t+PI*s.probe+rad(s.phase)),envelope:2*Math.abs(Math.cos(PI*s.probe+rad(s.phase)/2)),x:s.probe}),'Thay pha tương đối dịch vị trí các nút và bụng của tổng hai sóng.',{grade:11,time:true});
add('reflection_wave','Phản xạ tại đầu dây cố định','Sóng','wave',[P('probe','Khoảng cách tới đầu cố định',0,3,1,'m',.05),P('frequency','Tần số',.5,2,1,'Hz',.1)],[Q('incident','Li độ sóng tới','cm'),Q('reflected','Li độ phản xạ','cm'),Q('signal','Tổng li độ','cm')],'u phản xạ = −cos(ωt + kx)',s=>({incident:Math.cos(2*PI*s.frequency*s.t-PI*s.probe),reflected:-Math.cos(2*PI*s.frequency*s.t+PI*s.probe),signal:Math.cos(2*PI*s.frequency*s.t-PI*s.probe)-Math.cos(2*PI*s.frequency*s.t+PI*s.probe)}),'Tại đầu cố định, sóng phản xạ ngược pha để tổng li độ luôn bằng không.',{grade:11,time:true});
add('wave_packet','Chồng chất và bó sóng','Sóng','dualwave',[P('probe','Vị trí',-3,3,0,'m',.1),P('difference','Chênh số sóng',.2,2,.5,'rad/m',.1)],[Q('signal','Li độ tổng tương đối'),Q('envelope','Biên độ bao'),Q('group','Tốc độ nhóm','m/s')],'u = 2 cos(Δk(x − vt)/2) cos(k(x − vt))',s=>({signal:2*Math.cos(s.difference*(s.probe-s.t)/2)*Math.cos(4*(s.probe-s.t)),envelope:2*Math.abs(Math.cos(s.difference*(s.probe-s.t)/2)),group:1}),'Chồng chất hai sóng gần nhau tạo đường bao; trong môi trường không tán sắc này, bao và pha cùng tốc độ.',{grade:11,time:true,extra:true});
add('spring_parallel','Hai lò xo ghép song song','Dao động','spring',[P('k1','Độ cứng lò xo 1',10,100,30,'N/m',2),P('k2','Độ cứng lò xo 2',10,100,50,'N/m',2),M()],[Q('effective','Độ cứng tương đương','N/m'),Q('period','Chu kì','s'),Q('extension','Độ dãn khi treo','m')],'k = k₁ + k₂',s=>({effective:s.k1+s.k2,period:2*PI*Math.sqrt(s.mass/(s.k1+s.k2)),extension:s.mass*G/(s.k1+s.k2)}),'Lò xo song song cùng độ dãn và chia nhau lực đỡ vật.',{grade:11,extra:true});
add('spring_series','Hai lò xo ghép nối tiếp','Dao động','spring',[P('k1','Độ cứng lò xo 1',10,100,30,'N/m',2),P('k2','Độ cứng lò xo 2',10,100,50,'N/m',2),M()],[Q('effective','Độ cứng tương đương','N/m'),Q('period','Chu kì','s'),Q('extension','Tổng độ dãn','m')],'1/k = 1/k₁ + 1/k₂',s=>({effective:s.k1*s.k2/(s.k1+s.k2),period:2*PI*Math.sqrt(s.mass*(s.k1+s.k2)/(s.k1*s.k2)),extension:s.mass*G*(1/s.k1+1/s.k2)}),'Lò xo nối tiếp chịu cùng lực và cộng độ dãn; hệ mềm hơn từng lò xo.',{grade:11,extra:true});
add('resonance_power','Công suất hấp thụ gần cộng hưởng','Dao động','spring',[P('frequency','Tần số lực cưỡng bức',.2,3,1,'Hz',.05),P('damping','Hệ số cản',.2,5,1,'kg/s',.1)],[Q('power','Công suất trung bình','W'),Q('amplitude','Biên độ ổn định','m'),Q('natural','Tần số riêng','Hz')],'P̄ = ½bω²A²; A = F₀/√((k−mω²)²+b²ω²)',s=>{const w=2*PI*s.frequency,a=1/Math.hypot(40-w*w,s.damping*w);return {amplitude:a,power:.5*s.damping*w*w*a*a,natural:Math.sqrt(40)/(2*PI)};},'Lực cản ảnh hưởng độ sắc của đỉnh công suất; năng lượng vào cân bằng tổn hao ở trạng thái ổn định.',{grade:11,extra:true,limit:'m = 1 kg, k = 40 N/m, F₀ = 1 N. Chỉ xét nghiệm ổn định sau khi dao động quá độ tắt.'});
// 14 distinct optical arrangements.
add('ray_slab','Tia sáng qua bản mặt song song','Quang học','ray',[A('angle','Góc tới'),P('index','Chiết suất bản',1,1.8,1.5,'',.02),P('thickness','Bề dày bản',.2,3,1,'cm',.1)],[Q('shift','Độ lệch ngang','cm'),Q('refracted','Góc trong bản','°'),Q('emergent','Góc ló','°')],'d = h sin(i−r)/cos r',s=>{const i=rad(s.angle),r=Math.asin(Math.sin(i)/s.index);return {shift:s.thickness*Math.sin(i-r)/Math.cos(r),refracted:r*180/PI,emergent:s.angle};},'Tia ló song song tia tới nhưng bị dịch ngang sau khi qua bản.',{grade:11,extra:true});
add('apparent_depth','Độ sâu biểu kiến của vật dưới nước','Quang học','ray',[P('depth','Độ sâu thật',.2,3,1,'m',.1),P('index','Chiết suất chất lỏng',1,1.8,1.33,'',.01)],[Q('apparent','Độ sâu biểu kiến','m'),Q('rise','Độ nâng ảnh','m'),Q('ratio','Độ sâu thật / biểu kiến')],'h′ ≈ h/n',s=>({apparent:s.depth/s.index,rise:s.depth*(1-1/s.index),ratio:s.index}),'Nhìn gần phương vuông góc mặt nước, ảnh của vật gần mặt nước hơn vật thật.',{grade:11,extra:true,limit:'Quan sát từ không khí, góc nhỏ; mặt phân cách phẳng.'});
add('lens_power','Độ tụ của thấu kính','Quang học','lens',[P('focal','Tiêu cự',5,100,25,'cm',1)],[Q('power','Độ tụ','D'),Q('focus','Tiêu cự','m'),Q('parallel','Tia song song hội tụ','',0)],'D = 1/f (f tính bằng mét)',s=>({power:100/s.focal,focus:s.focal/100,parallel:1}),'Độ tụ lớn tương ứng tiêu cự ngắn; phải đổi centimét sang mét trước khi tính.',{grade:11,extra:true});
add('lenses_contact','Hệ hai thấu kính sát nhau','Quang học','lens',[P('power1','Độ tụ kính 1',-10,10,4,'D',.5),P('power2','Độ tụ kính 2',-10,10,2,'D',.5)],[Q('power','Độ tụ hệ','D'),Q('focal','Tiêu cự hệ','cm'),Q('type','Hội tụ: 1; phân kì: −1','',0)],'D hệ = D₁ + D₂',s=>({power:s.power1+s.power2,focal:Math.abs(s.power1+s.power2)<1e-9?null:100/(s.power1+s.power2),type:Math.sign(s.power1+s.power2)}),'Hai kính có thể bù độ tụ; hệ có độ tụ 0 không có tiêu điểm hữu hạn.',{grade:11,extra:true,limit:'Thấu kính mỏng đặt sát nhau, trong không khí; xấp xỉ gần trục.'});
add('magnifier','Kính lúp khi ngắm chừng ở vô cực','Quang học','lens',[P('focal','Tiêu cự kính',2,15,5,'cm',.5)],[Q('magnification','Bội giác'),Q('distance','Khoảng vật–kính','cm'),Q('power','Độ tụ','D')],'G∞ = Đ/f',s=>({magnification:25/s.focal,distance:s.focal,power:100/s.focal}),'Vật ở tiêu diện cho chùm ló song song và ảnh ở vô cực.',{grade:11,extra:true,limit:'Mắt đặt sát kính, khoảng cực cận quy ước Đ = 25 cm; bội giác là góc, không phải kích thước ảnh trên màn.'});
add('telescope','Kính thiên văn khúc xạ','Quang học','lens',[P('objective','Tiêu cự vật kính',20,100,60,'cm',5),P('eyepiece','Tiêu cự thị kính',2,10,5,'cm',.5)],[Q('magnification','Bội giác góc có dấu'),Q('lengthNow','Chiều dài ống','cm'),Q('ratio','Tỉ số tiêu cự')],'G = −f₁/f₂; l = f₁ + f₂',s=>({magnification:-s.objective/s.eyepiece,lengthNow:s.objective+s.eyepiece,ratio:s.objective/s.eyepiece}),'Vật kính tạo ảnh trung gian; thị kính quan sát ảnh ấy. Dấu âm chỉ ảnh đảo.',{grade:11,extra:true,limit:'Ngắm chừng ở vô cực; hai kính hội tụ mỏng, đồng trục; không mô phỏng quang sai.'});
add('microscope','Kính hiển vi quang học','Quang học','lens',[P('objective','Tiêu cự vật kính',.5,2,1,'cm',.1),P('eyepiece','Tiêu cự thị kính',2,8,5,'cm',.5),P('interval','Độ dài quang học',10,20,16,'cm',1)],[Q('magnification','Bội giác góc'),Q('linear','Phóng đại của vật kính'),Q('ocular','Bội giác thị kính')],'|G| ≈ δĐ/(f₁f₂)',s=>({magnification:s.interval*25/(s.objective*s.eyepiece),linear:s.interval/s.objective,ocular:25/s.eyepiece}),'Bội giác toàn hệ là tích phóng đại vật kính và bội giác thị kính trong xấp xỉ này.',{grade:11,extra:true});
add('grating','Cách tử nhiễu xạ','Quang học','spectrum',[P('lines','Số vạch trên mm',100,1000,500,'vạch/mm',10,0),P('wavelength','Bước sóng',380,750,550,'nm',10,0),P('order','Bậc cực đại',1,3,1,'',1,0)],[Q('angle','Góc cực đại','°'),Q('spacing','Chu kì cách tử','µm'),Q('allowed','Bậc này tồn tại','',0)],'d sinθ = mλ',s=>{const a=s.order*s.wavelength*s.lines/1e6;return {angle:a<=1?Math.asin(a)*180/PI:null,spacing:1000/s.lines,allowed:a<=1?1:0};},'Không phải mọi bậc đều tồn tại: độ lớn mλ không được vượt chu kì cách tử.',{grade:11,extra:true});
add('resolving_power','Giới hạn phân giải của khẩu độ tròn','Quang học','spectrum',[P('diameter','Đường kính khẩu độ',1,100,20,'mm',1),P('wavelength','Bước sóng',380,750,550,'nm',10,0)],[Q('angle','Góc phân giải','µrad'),Q('arcseconds','Góc phân giải','arcsec'),Q('separation','Khoảng tách ở 1 km','mm')],'θ ≈ 1,22λ/D',s=>({angle:1.22*s.wavelength/s.diameter,arcseconds:1.22*s.wavelength/s.diameter*.206265,separation:1.22*s.wavelength/s.diameter}),'Khẩu độ lớn hơn giúp phân giải hai nguồn gần nhau tốt hơn trong giới hạn nhiễu xạ.',{grade:11,extra:true,limit:'Tiêu chuẩn Rayleigh, khẩu độ tròn lí tưởng, ánh sáng đơn sắc. Ảnh trên hình là biểu diễn nguyên tắc.'});
add('brewster','Góc Brewster','Quang học','ray',[P('index','Chiết suất môi trường 2',1,2,1.5,'',.02),P('index1','Chiết suất môi trường 1',1,1.5,1,'',.02)],[Q('angle','Góc Brewster','°'),Q('refracted','Góc khúc xạ','°'),Q('sum','Tổng hai góc','°')],'tan iB = n₂/n₁',s=>({angle:Math.atan(s.index/s.index1)*180/PI,refracted:90-Math.atan(s.index/s.index1)*180/PI,sum:90}),'Tại góc Brewster, tia phản xạ và tia khúc xạ vuông góc nhau.',{grade:11,extra:true,limit:'Môi trường điện môi không hấp thụ; công thức dành cho phân cực p. Không mô phỏng biên độ Fresnel đầy đủ.'});
add('inverse_square_light','Độ rọi từ nguồn sáng điểm','Quang học','light',[P('distance','Khoảng cách',.5,5,2,'m',.1),P('luminosity','Cường độ sáng',10,1000,100,'cd',10,0)],[Q('illuminance','Độ rọi','lx'),Q('sphere','Diện tích mặt cầu','m²'),Q('flux','Quang thông toàn phần','lm')],'E = I/r²',s=>({illuminance:s.luminosity/s.distance**2,sphere:4*PI*s.distance**2,flux:4*PI*s.luminosity}),'Cùng một nguồn điểm, bề mặt vuông góc nhận độ rọi nhỏ hơn khi ở xa hơn.',{grade:11,extra:true,limit:'Nguồn điểm đẳng hướng, không hấp thụ; độ rọi trên bề mặt vuông góc tia.'});
add('mirror_rotation','Xoay gương và độ lệch tia phản xạ','Quang học','ray',[P('rotation','Góc xoay gương',0,30,10,'°',1,0)],[Q('deviation','Độ quay tia phản xạ','°'),Q('normal','Độ quay pháp tuyến','°'),Q('ratio','Tỉ số hai góc')],'Δθ tia phản xạ = 2α',s=>({deviation:2*s.rotation,normal:s.rotation,ratio:2}),'Tia tới giữ nguyên: xoay gương một góc làm tia phản xạ quay gấp đôi góc đó.',{grade:11,extra:true});
add('pinhole','Ảnh qua lỗ nhỏ','Quang học','lens',[P('distance','Khoảng cách vật',.5,5,2,'m',.1),P('screen','Khoảng cách màn',.1,1,.3,'m',.05),P('height','Chiều cao vật',.1,2,1,'m',.1)],[Q('image','Chiều cao ảnh có dấu','cm'),Q('magnification','Độ phóng đại'),Q('ratio','Tỉ số khoảng cách')],'h′/h = −d′/d',s=>({image:-100*s.height*s.screen/s.distance,magnification:-s.screen/s.distance,ratio:s.screen/s.distance}),'Các tia đi thẳng qua lỗ nhỏ tạo ảnh đảo trên màn.',{grade:11,extra:true,limit:'Quang hình học, bỏ qua nhiễu xạ và kích thước lỗ; không dùng để dự đoán độ nét thực.'});
add('fiber_acceptance','Khẩu độ số của sợi quang','Quang học','ray',[P('core','Chiết suất lõi',1.45,1.6,1.5,'',.005,3),P('cladding','Chiết suất vỏ',1.3,1.44,1.4,'',.005,3)],[Q('aperture','Khẩu độ số NA'),Q('angle','Góc nhận cực đại','°'),Q('critical','Góc giới hạn lõi–vỏ','°')],'NA = √(n lõi² − n vỏ²)',s=>({aperture:Math.sqrt(s.core**2-s.cladding**2),angle:Math.asin(Math.min(1,Math.sqrt(s.core**2-s.cladding**2)))*180/PI,critical:Math.asin(s.cladding/s.core)*180/PI}),'Lõi có chiết suất lớn hơn vỏ giúp giữ tia bằng phản xạ toàn phần.',{grade:11,extra:true,limit:'Sợi quang bậc chiết suất, môi trường ngoài là không khí; xét tia kinh tuyến.'});
// 20 electrostatics and circuit experiments.
add('uniform_field','Hạt trong điện trường đều','Điện trường','field',[P('field','Cường độ điện trường',0,1000,300,'V/m',20,0),P('charge','Điện tích',-5,5,2,'µC',.1),P('mass','Khối lượng hạt',1,10,5,'mg',.2)],[Q('force','Lực điện có dấu','mN'),Q('acc','Gia tốc','m/s²'),Q('work','Công trên 10 cm','µJ')],'F = qE; a = qE/m',s=>({force:s.charge*s.field*.001,acc:s.charge*s.field/s.mass,work:s.charge*s.field*.1}),'Điện tích âm chịu lực ngược hướng điện trường; điện trường không phụ thuộc dấu điện tích thử.',{grade:11});
add('potential_point','Điện thế của điện tích điểm','Điện trường','field',[P('charge','Điện tích nguồn',-10,10,4,'nC',.5),P('distance','Khoảng cách tới nguồn',.1,3,1,'m',.05)],[Q('potential','Điện thế','V'),Q('field','Thành phần điện trường hướng ra','N/C'),Q('work','Thế năng của q₀ = 1 nC','nJ')],'V = kQ/r; E hướng ra = kQ/r²',s=>({potential:k*s.charge*1e-9/s.distance,field:k*s.charge*1e-9/s.distance**2,work:k*s.charge*1e-9/s.distance}),'Điện thế là đại lượng vô hướng có dấu; điện trường còn có phương và chiều.',{grade:11});
add('potential_pair','Điện thế trên trục của lưỡng cực','Điện trường','field',[P('charge','Độ lớn mỗi điện tích',1,10,4,'nC',.5),P('half','Nửa khoảng cách hai điện tích',.05,.3,.15,'m',.01),P('distance','Hoành độ điểm đo',.5,3,1,'m',.05)],[Q('potential','Điện thế tổng','V'),Q('near','Điện thế do +q','V'),Q('far','Điện thế do −q','V')],'V = kq/|x−a| − kq/|x+a|',s=>{const rPlus=Math.abs(s.distance-s.half),rMinus=Math.abs(s.distance+s.half),near=rPlus===0?null:k*s.charge*1e-9/rPlus,far=rMinus===0?null:-k*s.charge*1e-9/rMinus;return {potential:near===null||far===null?null:near+far,near,far};},'Điện thế các nguồn cộng đại số; hai đóng góp trái dấu không nhất thiết triệt tiêu.',{grade:11});
add('dipole_torque','Lưỡng cực trong điện trường đều','Điện trường','vectors',[P('moment','Mômen lưỡng cực',1,20,5,'nC·m',.5),P('field','Cường độ điện trường',10,1000,300,'V/m',10,0),P('angle','Góc với điện trường',0,180,60,'°',2,0)],[Q('torque','Mômen quay','µN·m'),Q('energy','Thế năng','µJ'),Q('net','Hợp lực','N')],'M = pE sinα; U = −pE cosα',s=>({torque:s.moment*s.field*.001*Math.sin(rad(s.angle)),energy:-s.moment*s.field*.001*Math.cos(rad(s.angle)),net:0}),'Trong điện trường đều, hợp lực bằng không nhưng lưỡng cực vẫn có thể chịu mômen quay.',{grade:11,extra:true});
add('capacitor_plate','Tụ điện phẳng theo hình học','Điện trường','capacitor',[P('area','Diện tích mỗi bản',10,200,100,'cm²',5),P('gap','Khoảng cách hai bản',.2,5,1,'mm',.1),U()],[Q('capacity','Điện dung','pF'),Q('charge','Điện tích bản dương','nC'),Q('field','Điện trường giữa bản','kV/m')],'C = ε₀S/d',s=>({capacity:eps*s.area*1e11/s.gap,charge:eps*s.area*1e8/s.gap*s.voltage,field:s.voltage/s.gap}),'Hai bản rộng hơn hoặc đặt gần hơn làm điện dung tăng.',{grade:11,limit:'Chân không, bản song song, bỏ qua hiệu ứng mép; tụ luôn nối nguồn điện áp giữ cố định.'});
add('dielectric','Điện môi khi tụ nối nguồn','Điện trường','capacitor',[P('dielectric','Hằng số điện môi',1,8,3,'',.2),P('base','Điện dung khi không khí',10,200,100,'pF',5),U()],[Q('capacity','Điện dung mới','pF'),Q('charge','Điện tích','nC'),Q('energy','Năng lượng','nJ')],'C = εrC₀; Q = CU; W = ½CU²',s=>({capacity:s.dielectric*s.base,charge:s.dielectric*s.base*s.voltage/1000,energy:.0005*s.dielectric*s.base*s.voltage**2}),'Khi vẫn nối nguồn, thêm điện môi làm điện dung và điện tích tăng, còn điện áp giữ nguyên.',{grade:11,limit:'Điện môi lấp đầy khe; nguồn giữ U cố định, không phải tụ cô lập. Bỏ qua đánh thủng.'});
add('capacitor_series','Tụ điện ghép nối tiếp','Điện trường','capacitor',[P('c1','Điện dung C₁',1,100,20,'µF',1),P('c2','Điện dung C₂',1,100,30,'µF',1),U()],[Q('capacity','Điện dung hệ','µF'),Q('u1','Điện áp tụ 1','V'),Q('u2','Điện áp tụ 2','V')],'1/C = 1/C₁ + 1/C₂',s=>({capacity:s.c1*s.c2/(s.c1+s.c2),u1:s.voltage*s.c2/(s.c1+s.c2),u2:s.voltage*s.c1/(s.c1+s.c2)}),'Hai tụ nối tiếp có cùng độ lớn điện tích nhưng có thể có điện áp khác nhau.',{grade:11});
add('capacitor_parallel','Tụ điện ghép song song','Điện trường','capacitor',[P('c1','Điện dung C₁',1,100,20,'µF',1),P('c2','Điện dung C₂',1,100,30,'µF',1),U()],[Q('capacity','Điện dung hệ','µF'),Q('q1','Điện tích tụ 1','µC'),Q('q2','Điện tích tụ 2','µC')],'C = C₁ + C₂',s=>({capacity:s.c1+s.c2,q1:s.c1*s.voltage,q2:s.c2*s.voltage}),'Hai tụ song song có cùng điện áp và tổng điện tích bằng tổng điện tích từng tụ.',{grade:11});
add('capacitor_force','Lực hút giữa hai bản tụ','Điện trường','capacitor',[P('area','Diện tích bản',10,200,100,'cm²',5),P('gap','Khe hở',.2,5,1,'mm',.1),U()],[Q('force','Lực hút','µN'),Q('pressure','Áp suất điện','mPa'),Q('field','Điện trường','kV/m')],'F = ½ε₀S(U/d)²',s=>({force:.5*eps*s.area*1e8*(s.voltage/s.gap)**2,pressure:.5*eps*(s.voltage/s.gap*1000)**2*1000,field:s.voltage/s.gap}),'Ở điện áp không đổi, giảm khe hở làm lực hút tăng theo nghịch đảo bình phương.',{grade:11,extra:true,limit:'Tụ phẳng nối nguồn, bỏ qua mép và biến dạng bản; chỉ xét lực tĩnh điện.'});
add('charge_quantization','Lượng tử hóa điện tích','Điện trường','particles',[P('electrons','Số electron dư',0,10000,1000,'electron',1,0)],[Q('charge','Điện tích có dấu','fC',4),Q('count','Số electron dư','',0),Q('unit','Độ lớn e','fC',6)],'q = −ne',s=>({charge:-s.electrons*e*1e15,count:s.electrons,unit:e*1e15}),'Điện tích thu được khi thêm electron có dấu âm và thay đổi theo từng bội của e.',{grade:11,limit:'Chấm trên hình đại diện nhóm electron, không dùng để đếm. Số electron là số nguyên.'});
add('drift','Vận tốc trôi của electron','Dòng điện','wire',[P('current','Cường độ dòng điện',.1,10,2,'A',.1),P('area','Tiết diện dây',.2,5,1,'mm²',.1)],[Q('drift','Độ lớn vận tốc trôi','mm/s',4),Q('density','Mật độ dòng','A/mm²'),Q('charge','Điện lượng trong 1 s','C')],'I = neSvd',s=>({drift:s.current/(8.5e28*e*s.area*1e-6)*1000,density:s.current/s.area,charge:s.current}),'Electron trôi chậm dù tín hiệu điện lan truyền nhanh; hai tốc độ này khác nhau.',{grade:11,limit:'Dây đồng n = 8,5×10²⁸ electron/m³; chấm chạy chậm để minh họa, không biểu diễn tốc độ tín hiệu.'});
add('wire_stretch','Kéo dây dẫn khi thể tích không đổi','Dòng điện','wire',[P('factor','Tỉ số chiều dài mới / cũ',1,4,2,'',.1),P('base','Điện trở ban đầu',1,20,5,'Ω',.5)],[Q('resistance','Điện trở mới','Ω'),Q('area','Tiết diện mới / cũ'),Q('ratio','Điện trở mới / cũ')],'R′ = R(l′/l)²',s=>({resistance:s.base*s.factor**2,area:1/s.factor,ratio:s.factor**2}),'Kéo dài dây vừa tăng chiều dài vừa giảm tiết diện; điện trở không chỉ tăng theo chiều dài.',{grade:11,limit:'Thể tích và điện trở suất không đổi; không xét tác động nhiệt hay hư hỏng vật liệu.'});
add('potentiometer','Biến trở con chạy','Dòng điện','circuit',[P('fraction','Phần chiều dài đang dùng',0,1,.5,'',.02),RR(),U()],[Q('output','Điện áp con chạy','V'),Q('upper','Điện trở đoạn trên','Ω'),Q('lower','Điện trở đoạn dưới','Ω')],'U ra = xU vào',s=>({output:s.fraction*s.voltage,upper:(1-s.fraction)*s.resistance,lower:s.fraction*s.resistance}),'Con chạy chia điện áp theo vị trí khi đầu ra không bị tải.',{grade:11,limit:'Biến trở đồng nhất; vôn kế có điện trở vô hạn, không mắc tải đầu ra.'});
add('voltage_divider','Mạch chia áp có tải','Dòng điện','circuit',[P('r1','Điện trở trên',10,1000,100,'Ω',10,0),P('r2','Điện trở dưới',10,1000,200,'Ω',10,0),P('load','Điện trở tải',10,2000,500,'Ω',10,0),U()],[Q('output','Điện áp có tải','V'),Q('unloaded','Điện áp không tải','V'),Q('current','Dòng qua tải','mA')],'U ra = U·(R₂ ∥ RL)/(R₁ + R₂ ∥ RL)',s=>{const r=s.r2*s.load/(s.r2+s.load),out=s.voltage*r/(s.r1+r);return {output:out,unloaded:s.voltage*s.r2/(s.r1+s.r2),current:1000*out/s.load};},'Tải làm thay đổi tỉ số chia áp; điện áp có tải nhỏ hơn điện áp không tải.',{grade:11});
add('kirchhoff_loop','Hai nguồn ngược chiều trong một vòng','Dòng điện','circuit',[P('source1','Suất điện động 1',0,12,9,'V',.5),P('source2','Suất điện động đối kháng',0,12,3,'V',.5),RR()],[Q('current','Dòng có dấu','A',3),Q('drop','Điện áp trên điện trở','V'),Q('power','Công suất tỏa nhiệt','W')],'I = (E₁ − E₂)/R',s=>({current:(s.source1-s.source2)/s.resistance,drop:s.source1-s.source2,power:(s.source1-s.source2)**2/s.resistance}),'Đảo thứ tự độ lớn hai nguồn làm dòng điện đảo chiều, nhưng công suất tỏa nhiệt vẫn không âm.',{grade:11,extra:true});
add('diode_model','Diode theo mô hình ngưỡng','Dòng điện','circuit',[P('voltage','Điện áp nguồn có dấu',-5,5,2,'V',.1),RR(),P('threshold','Ngưỡng thuận giả định',.2,1,.7,'V',.05)],[Q('current','Dòng thuận','mA'),Q('diode','Điện áp diode','V'),Q('power','Công suất điện trở','mW')],'I ≈ max(0, U − Uγ)/R',s=>{const i=Math.max(0,s.voltage-s.threshold)/s.resistance;return {current:i*1000,diode:i>0?s.threshold:s.voltage,power:i*i*s.resistance*1000};},'Diode dẫn thuận sau ngưỡng trong mô hình gần đúng; đây không phải đặc tuyến thực đầy đủ.',{grade:11,extra:true,limit:'Mô hình ngưỡng từng đoạn, bỏ qua dòng ngược và đánh thủng. Ngưỡng 0,7 V chỉ là lựa chọn gần đúng.'});
add('meter_loading','Vôn kế làm thay đổi mạch đo','Dòng điện','circuit',[P('meter','Điện trở vôn kế',100,10000,1000,'Ω',100,0),P('r1','Điện trở nguồn tương đương',10,1000,100,'Ω',10,0),P('r2','Điện trở cần đo áp',10,1000,200,'Ω',10,0),U()],[Q('measured','Điện áp khi mắc vôn kế','V'),Q('trueValue','Điện áp trước khi mắc','V'),Q('error','Độ giảm tương đối','%')],'Rm hữu hạn làm tải nhánh đo',s=>{const r=s.r2*s.meter/(s.r2+s.meter),v=s.voltage*r/(s.r1+r),v0=s.voltage*s.r2/(s.r1+s.r2);return {measured:v,trueValue:v0,error:v0===0?0:100*(1-v/v0)};},'Điện trở vôn kế càng lớn, ảnh hưởng của phép đo lên mạch càng nhỏ.',{grade:11});
add('max_power','Công suất tải và điện trở trong','Dòng điện','circuit',[P('load','Điện trở tải',.5,20,5,'Ω',.5),P('internal','Điện trở trong',.5,10,3,'Ω',.5),U()],[Q('power','Công suất tải','W'),Q('efficiency','Hiệu suất điện','%'),Q('current','Cường độ dòng','A')],'P tải = E²R/(R+r)²',s=>({power:s.voltage**2*s.load/(s.load+s.internal)**2,efficiency:100*s.load/(s.load+s.internal),current:s.voltage/(s.load+s.internal)}),'Công suất tải lớn nhất tại R = r, nhưng hiệu suất lúc đó chỉ bằng 50%.',{grade:11,extra:true});
add('battery_series','Bộ pin ghép nối tiếp','Dòng điện','circuit',[P('cells','Số pin',1,8,3,'',1,0),P('emf','Suất điện động mỗi pin',1,3,1.5,'V',.1),P('internal','Điện trở trong mỗi pin',.1,2,.5,'Ω',.1),RR()],[Q('current','Dòng qua tải','A'),Q('emfTotal','Suất điện động bộ','V'),Q('internalTotal','Điện trở trong bộ','Ω')],'E bộ = nE; r bộ = nr',s=>({current:s.cells*s.emf/(s.resistance+s.cells*s.internal),emfTotal:s.cells*s.emf,internalTotal:s.cells*s.internal}),'Ghép nối tiếp tăng cả suất điện động lẫn điện trở trong của bộ pin.',{grade:11});
add('battery_parallel','Bộ pin giống nhau ghép song song','Dòng điện','circuit',[P('cells','Số pin',1,8,3,'',1,0),P('emf','Suất điện động mỗi pin',1,3,1.5,'V',.1),P('internal','Điện trở trong mỗi pin',.1,2,.5,'Ω',.1),RR()],[Q('current','Dòng qua tải','A'),Q('emfTotal','Suất điện động bộ','V'),Q('internalTotal','Điện trở trong bộ','Ω')],'E bộ = E; r bộ = r/n',s=>({current:s.emf/(s.resistance+s.internal/s.cells),emfTotal:s.emf,internalTotal:s.internal/s.cells}),'Ghép song song pin giống nhau giữ nguyên suất điện động và giảm điện trở trong tương đương.',{grade:11,limit:'Các pin hoàn toàn giống nhau. Không dùng mô hình này để hướng dẫn ghép pin thực khác điện áp.'});
// 8 magnetism and alternating-current investigations.
add('wire_field','Từ trường quanh dây thẳng dài','Điện từ','magnetic',[P('current','Dòng điện có dấu',-10,10,5,'A',.5),P('distance','Khoảng cách tới dây',.01,.2,.05,'m',.005)],[Q('field','Từ trường có dấu','µT'),Q('circulation','B·2πr','µT·m'),Q('magnitude','Độ lớn B','µT')],'B = µ₀I/(2πr)',s=>({field:.2*s.current/s.distance,circulation:mu*s.current*1e6,magnitude:Math.abs(.2*s.current/s.distance)}),'Đổi chiều dòng điện làm chiều từ trường đảo; tăng khoảng cách làm B giảm.',{grade:12});
add('wire_pair','Lực giữa hai dòng điện song song','Điện từ','magnetic',[P('current1','Dòng dây 1',-10,10,5,'A',.5),P('current2','Dòng dây 2',-10,10,5,'A',.5),P('distance','Khoảng cách hai dây',.01,.2,.05,'m',.005)],[Q('force','Lực hút trên mỗi mét có dấu','mN/m'),Q('field','B do dây 1 tại dây 2','µT'),Q('direction','Hút: 1; đẩy: −1','',0)],'F/l = µ₀I₁I₂/(2πd)',s=>({force:.0002*s.current1*s.current2/s.distance,field:.2*s.current1/s.distance,direction:Math.sign(s.current1*s.current2)}),'Hai dòng cùng chiều hút nhau; hai dòng ngược chiều đẩy nhau.',{grade:12,extra:true});
add('ampere_loop','Tuần hoàn từ trường quanh dây','Điện từ','magnetic',[P('radius','Bán kính đường khảo sát',.01,.3,.1,'m',.01),P('current','Dòng xuyên qua vòng',0,10,5,'A',.5)],[Q('circulation','Tuần hoàn từ trường','µT·m'),Q('field','Từ trường trên vòng','µT'),Q('circumference','Độ dài đường kín','m')],'∮B·dl = µ₀I',s=>({circulation:mu*s.current*1e6,field:.2*s.current/s.radius,circumference:2*PI*s.radius}),'B giảm trên vòng lớn hơn, nhưng tích B với chu vi giữ nguyên.',{grade:12,extra:true});
add('flux_angle','Từ thông theo góc pháp tuyến','Điện từ','flux',[P('angle','Góc B với pháp tuyến',0,180,45,'°',2,0),P('field','Cảm ứng từ',.1,1,.5,'T',.05),P('area','Diện tích vòng',10,200,100,'cm²',5)],[Q('flux','Từ thông có dấu','mWb'),Q('maximum','Từ thông cực đại','mWb'),Q('projection','Diện tích chiếu có dấu','cm²')],'Φ = BS cosα',s=>({flux:s.field*s.area*.1*Math.cos(rad(s.angle)),maximum:s.field*s.area*.1,projection:s.area*Math.cos(rad(s.angle))}),'Góc trong công thức đo với pháp tuyến của vòng, không đo với mặt phẳng vòng.',{grade:12});
add('inductor_energy','Năng lượng của cuộn cảm','Điện từ','coil',[P('inductance','Độ tự cảm',10,500,100,'mH',10),P('current','Cường độ dòng',0,5,2,'A',.1)],[Q('energy','Năng lượng từ trường','mJ'),Q('fluxLink','Từ thông móc vòng','mWb'),Q('ratio','W / I²','mJ/A²')],'W = ½LI²',s=>({energy:.5*s.inductance*s.current**2,fluxLink:s.inductance*s.current,ratio:.5*s.inductance}),'Tăng dòng gấp đôi làm năng lượng từ trường tăng gấp bốn.',{grade:12,extra:true});
add('rl_response','Đóng mạch RL','Điện từ','coil',[P('inductance','Độ tự cảm',.1,2,1,'H',.1),RR(),U()],[Q('current','Dòng tức thời','A',4),Q('timeConstant','Hằng số thời gian','s',4),Q('energy','Năng lượng cuộn cảm','mJ')],'I = (U/R)(1 − exp(−Rt/L))',s=>{const i=s.voltage/s.resistance*(1-Math.exp(-s.resistance*s.t/s.inductance));return {current:i,timeConstant:s.inductance/s.resistance,energy:500*s.inductance*i*i};},'Dòng trong cuộn cảm không tăng tức thì lên giá trị ổn định khi đóng mạch.',{grade:12,time:true,extra:true,limit:'Cuộn cảm lí tưởng, điện trở tập trung R, I ban đầu bằng 0.'});
add('lc_oscillator','Dao động điện từ LC','Điện từ','coil',[P('inductance','Độ tự cảm',.1,2,1,'H',.1),P('capacity','Điện dung',10,1000,100,'µF',10),U()],[Q('frequency','Tần số riêng','Hz'),Q('electric','Năng lượng điện trường','mJ'),Q('magnetic','Năng lượng từ trường','mJ')],'f = 1/(2π√LC); Wđ + Wt = hằng số',s=>{const f=1/(2*PI*Math.sqrt(s.inductance*s.capacity*1e-6)),w=.0005*s.capacity*s.voltage**2;return {frequency:f,electric:w*Math.cos(2*PI*f*s.t)**2,magnetic:w*Math.sin(2*PI*f*s.t)**2};},'Năng lượng luân phiên giữa tụ và cuộn cảm trong mạch không có tổn hao.',{grade:12,time:true,extra:true,limit:'Mạch LC không điện trở, lúc đầu tụ có điện áp U và dòng bằng 0. Đồng hồ là thời gian của mô hình.'});
add('rlc_resonance','Cộng hưởng mạch RLC nối tiếp','Điện từ','coil',[P('frequency','Tần số nguồn',10,200,50,'Hz',2),P('inductance','Độ tự cảm',.05,1,.2,'H',.05),P('capacity','Điện dung',10,200,50,'µF',10),RR()],[Q('current','Dòng RMS','A',3),Q('impedance','Tổng trở','Ω'),Q('phase','Pha điện áp trừ dòng','°')],'Z = √(R² + (ωL − 1/ωC)²)',s=>{const x=2*PI*s.frequency*s.inductance-1/(2*PI*s.frequency*s.capacity*1e-6),z=Math.hypot(s.resistance,x);return {current:12/z,impedance:z,phase:Math.atan2(x,s.resistance)*180/PI};},'Tại cộng hưởng, cảm kháng và dung kháng bù nhau, dòng RMS đạt cực đại.',{grade:12,extra:true,limit:'Nguồn 12 V RMS, các phần tử lí tưởng; chỉ xét trạng thái ổn định hình sin.'});
// 3 thermal and 3 modern-physics investigations.
add('newton_cooling','Làm nguội theo định luật Newton','Vật lí nhiệt','thermal',[P('initial','Nhiệt độ ban đầu',40,100,80,'°C',2),P('room','Nhiệt độ môi trường',10,35,25,'°C',1),P('rate','Hệ số nguội',.02,.5,.1,'s⁻¹',.02)],[Q('temperature','Nhiệt độ vật','°C'),Q('difference','Chênh nhiệt độ','°C'),Q('cooling','Độ lớn tốc độ nguội','°C/s')],'T = Tmt + (T₀−Tmt)e⁻ᵏᵗ',s=>({temperature:s.room+(s.initial-s.room)*Math.exp(-s.rate*s.t),difference:(s.initial-s.room)*Math.exp(-s.rate*s.t),cooling:s.rate*(s.initial-s.room)*Math.exp(-s.rate*s.t)}),'Vật nguội nhanh hơn khi chênh lệch nhiệt độ với môi trường lớn hơn.',{grade:12,time:true,extra:true,limit:'Nhiệt độ vật đồng đều, môi trường giữ cố định; hệ số trao đổi nhiệt hiệu dụng không đổi.'});
add('carnot','Giới hạn hiệu suất động cơ nhiệt','Vật lí nhiệt','thermal',[P('hot','Nhiệt độ nguồn nóng',400,1000,600,'K',10,0),P('cold','Nhiệt độ nguồn lạnh',200,350,300,'K',10,0),P('heat','Nhiệt nhận vào',100,1000,500,'J',20)],[Q('efficiency','Hiệu suất cực đại','%'),Q('work','Công cực đại','J'),Q('rejected','Nhiệt thải tối thiểu','J')],'ηmax = 1 − Tc/Th',s=>({efficiency:100*(1-s.cold/s.hot),work:s.heat*(1-s.cold/s.hot),rejected:s.heat*s.cold/s.hot}),'Không thể đổi toàn bộ nhiệt nhận từ nguồn nóng thành công trong chu trình hai nguồn.',{grade:12,extra:true,limit:'Giới hạn Carnot của chu trình thuận nghịch; nhiệt độ tuyệt đối K. Động cơ thực thường có hiệu suất thấp hơn.'});
add('adiabatic','Nén khí đoạn nhiệt thuận nghịch','Khí lí tưởng','gas',[P('ratio','Tỉ số thể tích đầu / sau',1,4,2,'',.1),T()],[Q('finalTemp','Nhiệt độ sau','K'),Q('pressureRatio','Áp suất sau / đầu'),Q('workOn','Công khí nhận','J')],'TV^(γ−1) = hằng số',s=>{const tf=s.temp*s.ratio**.4;return {finalTemp:tf,pressureRatio:s.ratio**1.4,workOn:.1*R/.4*(tf-s.temp)};},'Nén đoạn nhiệt làm khí nóng lên dù không nhận nhiệt lượng.',{grade:12,extra:true,limit:'0,1 mol khí lí tưởng hai nguyên tử, γ = 1,4; đoạn nhiệt thuận nghịch, nhiệt dung không đổi.'});
add('photoelectric','Hiệu ứng quang điện ngoài','Vật lí hiện đại','light',[P('wavelength','Bước sóng chiếu',200,800,400,'nm',10,0),P('workFunction','Công thoát',1,5,2,'eV',.1)],[Q('kinetic','Động năng cực đại','eV'),Q('stopping','Điện áp hãm','V'),Q('threshold','Giới hạn quang điện','nm')],'Kmax = hc/λ − A',s=>({kinetic:Math.max(0,1239.841984/s.wavelength-s.workFunction),stopping:Math.max(0,1239.841984/s.wavelength-s.workFunction),threshold:1239.841984/s.workFunction,emitted:1239.841984/s.wavelength>=s.workFunction?1:0}),'Photon không đủ năng lượng thì không gây bật electron, dù vẫn chiếu sáng.',{grade:12,extra:true,limit:'Một photon truyền năng lượng cho một electron. Khi dưới ngưỡng, Kmax hiển thị 0 vì không có electron phát ra; không mô phỏng dòng bão hòa.'});
add('debroglie','Bước sóng de Broglie của electron','Vật lí hiện đại','particles',[P('voltage','Điện áp tăng tốc',1,1000,100,'V',10,0)],[Q('wavelength','Bước sóng de Broglie','nm',4),Q('speed','Tốc độ electron','10⁶ m/s'),Q('energy','Động năng','eV')],'λ = h/√(2meU)',s=>({wavelength:1.22642597/Math.sqrt(s.voltage),speed:Math.sqrt(2*e*s.voltage/9.1093837e-31)/1e6,energy:s.voltage}),'Electron được tăng tốc mạnh hơn có động lượng lớn hơn và bước sóng nhỏ hơn.',{grade:12,extra:true,limit:'Electron bắt đầu gần như đứng yên; xấp xỉ phi tương đối tính cho điện áp trong miền đã chọn.'});
add('binding_energy','Độ hụt khối và năng lượng liên kết','Hạt nhân','particles',[P('defect','Độ hụt khối',.001,1,.05,'u',.005,3),P('nucleons','Số nucleon',2,200,20,'',1,0)],[Q('energy','Năng lượng liên kết','MeV'),Q('perNucleon','Năng lượng trên nucleon','MeV'),Q('joule','Năng lượng','pJ')],'E liên kết = Δmc²',s=>({energy:s.defect*931.494102,perNucleon:s.defect*931.494102/s.nucleons,joule:s.defect*931.494102*.1602176634}),'Năng lượng liên kết trên mỗi nucleon cần xét cùng số nucleon, không chỉ tổng năng lượng.',{grade:12,limit:'Khảo sát quan hệ E = Δmc²; hai thông số do người học chọn, không đại diện một đồng vị đã tra cứu.'});
specs.find(e=>e.id==='vector_sum').params.find(p=>p.key==='angle').max=180;
specs.find(e=>e.id==='ray_slab').params.find(p=>p.key==='angle').max=65;
export const atlasExperiments=[...specs.map(x=>({...x,atlas:true})),...expansionExperiments];
export const atlasById=Object.fromEntries(atlasExperiments.map(e=>[e.id,e]));
export function evaluateAtlas(id,state){const experiment=atlasById[id];return experiment?{...state,t:state.t||0,...experiment.compute({...state,t:state.t||0})}:null;}
